    } else {
      console.error('TemplateManager.generateImages is not available');
      if (window.UI && typeof UI.showMessage === 'function') {
        UI.showMessage('template-status', 'Internal error: generator not initialised.', 'error');
      }
    }
  });
}

B) js/features/generation/pollinations.js — after the fetch call and before clearTimeout, add:

console.log('Pollinations → response', response.status, 'type', response.type, 'content-type=', response.headers.get('content-type'), 'url', response.url);

Then update the non-ok block to:

if (!response.ok) {
  console.warn(`Pollinations → HTTP ${response.status}`);
  const retryable = [429, 502, 503, 504].includes(response.status);
  if (retryable && retries > 0) {
    const base = response.status === 429 ? 10000 : 5000; // 429: longer backoff
    const delay = base + Math.random() * base;
    console.warn(`Pollinations → Server/Rate limit ${response.status}, retrying in ${Math.round(delay)}ms (${retries} left)`);
    await new Promise(r => setTimeout(r, delay));
    return this.generateOne(prompt, seed, retries - 1);
  }
  throw new Error(`HTTP ${response.status}`);
}

C) js/features/generation/stability.js — when response.ok is false, read and log body:

if (!response.ok) {
  const text = await response.text().catch(() => '(failed to read body)');
  console.error('Stability API error', response.status, text);
  throw new Error(`Stability API error: ${response.status} ${text}`);
}

Notes and rationale:
- The TemplateManager guard is defensive: some builds load scripts in different orders (I saw a main_.js and template_.js variants in the repo); this prevents the uncaught TypeError and surfaces a clearer message.
- Treating 429 as retryable with longer backoff increases chance of successful generation for rate-limited APIs without spamming the endpoint. Also adding response header logs will make it immediately clear if the endpoint is returning HTML, an opaque response, or missing CORS headers.
- Improved Stability logging will allow us to see error messages returned by Stability.ai and fix the request format or credentials accordingly.

